export class LocalStorageHandler {
	constructor() {
		return new Proxy(this, this);
	}
	get(target, prop) {
		try {
			return JSON.parse(localStorage.getItem(prop));
		} catch (e) {
			console.warn("Unable to load value from localstorage");
			return null;
		}
	}

	set(target, prop, value) {
		try {
			localStorage.setItem(prop, JSON.stringify(value));
			return true;
		} catch (e) {
			console.warn("Unable to store value to localstorage");
			return false;
		}
	}
}

export const storeExists = (store) =>
	chrome && "storage" in chrome && store in chrome.storage;

export const setChromeStorageItem = (store) => (key, value) =>
	new Promise((resolve) => {
		if (storeExists(store)) {
			chrome.storage[store].set({ [key]: value }, resolve);
		} else {
			localStorage.setItem(key, value);
			resolve();
		}
	});

export const getChromeStorageItem = (store) => (key) =>
	new Promise((resolve, reject) => {
		const rejectionMessage = `item with key [${key}] does not exist`;

		if (storeExists(store)) {
			chrome.storage[store].get(key, (items) =>
				key in items ? resolve(items[key]) : reject(rejectionMessage)
			);
		} else {
			const item = localStorage.getItem(key);
			item !== null ? resolve(item) : reject(rejectionMessage);
		}
	});

export const getChromeLocalStorageItem = getChromeStorageItem("local");
export const setChromeLocalStorageItem = setChromeStorageItem("local");
export const getChromeSyncStorageItem = getChromeStorageItem("sync");
export const setChromeSyncStorageItem = setChromeStorageItem("sync");
