import { fireEvent } from "./analytics";

const errorToJson = (error) => {
	if (!(error instanceof Error)) return JSON.stringify(error);

	const obj = {};

	Object.getOwnPropertyNames(error).forEach((key) => {
		obj[key] = error[key];
	}, error);
	return JSON.stringify(obj);
};

const getVersion = () => {
	try {
		if (window.location.href.indexOf("chrome-extension://") !== -1) {
			return chrome.runtime.getManifest().version;
		}
	} catch (_) {}

	return "null";
};

const _legacyReport = async (event, where, description) => {
	const version = getVersion();
	const [date] = new Date().toLocaleString("no-NB").split(",");

	fireEvent(event, { version, date, description, where });
};

const _legacyReportError = async (error, where) => {
	if (typeof error !== "string") error = errorToJson(error);

	_legacyReport("error", where, error);
};

export async function trackErrors() {
	if (!window.ga) return;

	window.addEventListener("error", (errorEvent) => {
		const error = errorToJson(errorEvent.error ? errorEvent.error : errorEvent);
		_legacyReportError(error, "window.onerror");
	});

	window.addEventListener("unhandledrejection", (event) => {
		const error = event.reason ? event.reason : "unhandled rejection";
		_legacyReportError(error, "window.onunhandledrejection");
	});
}
